import os
import sys

def psys(command):
	print(command)
	os.system(command)


def main():

	folder = "test_data_sweep_normalized"
	index = 0
	matlab_script = "matlab -batch "
	for filename in os.listdir(folder):
		file_path = os.path.join(folder, filename)
		if os.path.isfile(file_path):
			frequency = filename.split('_F')[1].split('_D')[0]
			degree = filename.split('_D')[1].split('_N')[0]
			snr = filename.split('_N')[1].split('.csv')[0]
			testname = f"test_{index}_F{frequency}_D{degree}_N{snr}"
			testdir = f"auto_tests_sweep\{testname}"
			#os.mkdir(testdir)
			psys(f"copy {file_path} {testdir}\data.csv")
			psys(f"csv_to_hex.exe {testdir}\data.csv {testdir}\data.hex")
			matlab_script += f"oracle_modified('{testdir}'); "
			
		index += 1
		
	print(matlab_script)







if __name__ == "__main__":
	main()
	
	
	
